CREATE SCHEMA billing;
CREATE TABLE billing.invoice (id int PRIMARY KEY, total numeric);
CREATE TABLE public.invoice  (id int PRIMARY KEY, note text);

SHOW search_path;                 -- "$user", public
SELECT * FROM invoice;            -- resolves to public.invoice

SET search_path = billing, public;
SELECT * FROM invoice;            -- now billing.invoice

SELECT current_database(), current_schema();   -- e.g. shop | billing

CREATE TABLE payment (
    id        bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    reference text NOT NULL CHECK (length(reference) <= 40),
    amount    numeric(12, 2) NOT NULL,
    refunded  boolean NOT NULL DEFAULT false,
    client_ip inet
);
INSERT INTO payment (reference, amount, client_ip)
VALUES ('INV-1', 0.10, '203.0.113.7'), ('INV-2', 0.20, NULL);

SELECT sum(amount) FROM payment;                   -- 0.30 (exact)
SELECT 0.1::float8 + 0.2::float8 = 0.3::float8;    -- f   (floats are approximate)
SELECT pg_typeof(amount), pg_typeof('42'::int) FROM payment LIMIT 1;
-- numeric | integer

