SET TimeZone = 'UTC';
CREATE TABLE login (at timestamptz NOT NULL);
INSERT INTO login VALUES ('2026-03-10 18:30:00+04');   -- an instant
SELECT at FROM login;                       -- 2026-03-10 14:30:00+00

SET TimeZone = 'America/New_York';
SELECT at FROM login;                       -- 2026-03-10 10:30:00-04 (same instant)

SELECT at AT TIME ZONE 'Asia/Yerevan' FROM login;   -- 2026-03-10 18:30:00 (wall clock)
SELECT '2026-01-31'::date + interval '1 month';     -- 2026-02-28 00:00:00
