CREATE ROLE app_owner NOLOGIN;
CREATE ROLE app_ro NOLOGIN;
CREATE ROLE app_rw NOLOGIN;
CREATE SCHEMA app AUTHORIZATION app_owner;

GRANT USAGE ON SCHEMA app TO app_ro, app_rw;
-- tables app_owner creates later get these privileges automatically
ALTER DEFAULT PRIVILEGES FOR ROLE app_owner IN SCHEMA app
    GRANT SELECT ON TABLES TO app_ro;
ALTER DEFAULT PRIVILEGES FOR ROLE app_owner IN SCHEMA app
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO app_rw;

CREATE ROLE api LOGIN PASSWORD 'change-me' IN ROLE app_rw;
CREATE ROLE analyst LOGIN PASSWORD 'change-me' IN ROLE app_ro;

SET ROLE app_owner;
CREATE TABLE app.orders (id int PRIMARY KEY);
RESET ROLE;
SELECT has_table_privilege('analyst', 'app.orders', 'SELECT');   -- t
SELECT has_table_privilege('analyst', 'app.orders', 'INSERT');   -- f

CREATE TABLE account (id int PRIMARY KEY, profile jsonb NOT NULL);
INSERT INTO account VALUES
 (1, '{"plan": "pro", "address": {"city": "Yerevan"}, "tags": ["beta", "vip"]}'),
 (2, '{"plan": "free", "address": {"city": "Gyumri"}}');

SELECT id, profile ->> 'plan' AS plan,
       profile -> 'address' ->> 'city' AS city
FROM account WHERE profile @> '{"plan": "pro"}';    -- 1 | pro | Yerevan

SELECT id FROM account WHERE profile -> 'tags' ? 'vip';   -- 1

