CREATE INDEX account_profile_gin ON account USING gin (profile jsonb_path_ops);

CREATE TYPE ticket_status AS ENUM ('open', 'in_progress', 'closed');
CREATE DOMAIN positive_int AS int CHECK (VALUE > 0);

CREATE TABLE ticket (
    id       int PRIMARY KEY,
    status   ticket_status NOT NULL DEFAULT 'open',
    priority positive_int NOT NULL,
    tags     text[] NOT NULL DEFAULT '{}'
);
INSERT INTO ticket VALUES (1, 'open', 2, '{bug,ui}'), (2, 'closed', 1, '{docs}');

SELECT id FROM ticket WHERE 'bug' = ANY(tags);            -- 1
SELECT id, unnest(tags) AS tag FROM ticket ORDER BY id;   -- 1 bug, 1 ui, 2 docs
SELECT status FROM ticket ORDER BY status;                -- open, closed (enum order)
INSERT INTO ticket VALUES (3, 'open', 0, '{}');
-- ERROR: value for domain positive_int violates check constraint

