CREATE TABLE orders (id bigint PRIMARY KEY, customer_id int, total numeric);
INSERT INTO orders SELECT g, g % 5000, g % 97 FROM generate_series(1, 300000) g;
ANALYZE orders;

EXPLAIN (ANALYZE, BUFFERS)
SELECT * FROM orders WHERE customer_id = 42;
-- Gather (actual rows=60)
