--        Buffers: shared hit=1911

CREATE INDEX orders_customer_idx ON orders (customer_id);
EXPLAIN (ANALYZE, BUFFERS)
SELECT * FROM orders WHERE customer_id = 42;
-- Bitmap Heap Scan on orders (actual rows=60)
--   Buffers: shared hit=60 read=2         <- 62 pages instead of 1911

CREATE TABLE t (id int PRIMARY KEY);

BEGIN;
CREATE TABLE temp_report (x int);       -- DDL inside a transaction
INSERT INTO t VALUES (1);
SAVEPOINT before_risky;
INSERT INTO t VALUES (1);               -- ERROR: duplicate key
SELECT 1;                               -- ERROR: current transaction is aborted
ROLLBACK TO SAVEPOINT before_risky;     -- error cleared, row 1 still pending
INSERT INTO t VALUES (2);
ROLLBACK;                               -- undoes everything, even CREATE TABLE

SELECT to_regclass('temp_report');      -- NULL: the table was never created
SELECT count(*) FROM t;                 -- 0

ALTER ROLE CURRENT_USER SET idle_in_transaction_session_timeout = '60s';

CREATE TABLE account (id int PRIMARY KEY, balance numeric NOT NULL);
INSERT INTO account VALUES (1, 100), (2, 0);

CREATE FUNCTION transfer(src int, dst int, amount numeric)
RETURNS numeric LANGUAGE plpgsql AS $$
DECLARE
    left_over numeric;
BEGIN
    UPDATE account SET balance = balance - amount
    WHERE id = src RETURNING balance INTO left_over;
    IF left_over < 0 THEN
        RAISE EXCEPTION 'insufficient funds in account %', src;
    END IF;
    UPDATE account SET balance = balance + amount WHERE id = dst;
    RETURN left_over;
END $$;

SELECT transfer(1, 2, 30);    -- 70
SELECT transfer(1, 2, 500);   -- ERROR: insufficient funds in account 1
SELECT * FROM account ORDER BY id;   -- 1 | 70, 2 | 30

CREATE TABLE sale (id int PRIMARY KEY, region text, amount numeric, sold_on date);
INSERT INTO sale VALUES (1, 'north', 100, '2026-05-01'),
                        (2, 'south', 50,  '2026-05-01'),
                        (3, 'north', 70,  '2026-05-02');

CREATE MATERIALIZED VIEW daily_sales AS
SELECT sold_on, region, sum(amount) AS total, count(*) AS n
FROM sale GROUP BY sold_on, region;
CREATE UNIQUE INDEX ON daily_sales (sold_on, region);   -- needed for CONCURRENTLY

INSERT INTO sale VALUES (4, 'south', 30, '2026-05-02');
SELECT count(*) FROM daily_sales;                       -- 3 (stale)
REFRESH MATERIALIZED VIEW CONCURRENTLY daily_sales;
SELECT * FROM daily_sales ORDER BY sold_on, region;
-- 2026-05-01 north 100 1 / 2026-05-01 south 50 1
-- 2026-05-02 north 70 1  / 2026-05-02 south 30 1

CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE doc (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
                  title text, created_at timestamptz NOT NULL);
INSERT INTO doc (title, created_at)
SELECT 'report ' || md5(g::text), '2026-01-01'::timestamptz + g * interval '1 min'
FROM generate_series(1, 200000) g;

CREATE INDEX doc_title_trgm ON doc USING gin (title gin_trgm_ops);
CREATE INDEX doc_created_brin ON doc USING brin (created_at);
ANALYZE doc;

EXPLAIN SELECT id FROM doc WHERE title ILIKE '%abc12%';
-- Bitmap Index Scan on doc_title_trgm
EXPLAIN SELECT count(*) FROM doc
WHERE created_at BETWEEN '2026-02-01' AND '2026-02-02';
-- Bitmap Index Scan on doc_created_brin

SELECT pg_size_pretty(pg_relation_size('doc_created_brin'));   -- e.g. 24 kB

CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE booking (
    room   int NOT NULL,
    during tstzrange NOT NULL,
    EXCLUDE USING gist (room WITH =, during WITH &&)
);
INSERT INTO booking VALUES (1, '[2026-06-01 10:00+00, 2026-06-01 12:00+00)');
INSERT INTO booking VALUES (1, '[2026-06-01 12:00+00, 2026-06-01 13:00+00)');  -- ok, adjacent
INSERT INTO booking VALUES (2, '[2026-06-01 11:00+00, 2026-06-01 12:00+00)');  -- ok, other room
INSERT INTO booking VALUES (1, '[2026-06-01 11:30+00, 2026-06-01 12:30+00)');
-- ERROR: conflicting key value violates exclusion constraint "booking_room_during_excl"

SELECT room FROM booking
WHERE during @> '2026-06-01 11:15+00'::timestamptz ORDER BY room;   -- 1, 2

CREATE TABLE task (id int PRIMARY KEY, title text, status text,
                   updated_at timestamptz);

CREATE FUNCTION task_touch() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
        PERFORM pg_notify('task_events',
                          json_build_object('id', NEW.id, 'status', NEW.status)::text);
    END IF;
    RETURN NEW;                       -- BEFORE trigger: the row to write
END $$;

CREATE TRIGGER task_touch BEFORE INSERT OR UPDATE ON task
FOR EACH ROW EXECUTE FUNCTION task_touch();

LISTEN task_events;
INSERT INTO task (id, title, status) VALUES (1, 'Write docs', 'open');
UPDATE task SET status = 'done' WHERE id = 1;
-- Asynchronous notification "task_events" with payload {"id" : 1, "status" : "done"}
SELECT updated_at IS NOT NULL FROM task;   -- t

CREATE TABLE counter (id int PRIMARY KEY, n int) WITH (autovacuum_enabled = off);
INSERT INTO counter SELECT g, 0 FROM generate_series(1, 10000) g;
UPDATE counter SET n = n + 1;       -- 10000 new versions, 10000 dead ones
UPDATE counter SET n = n + 1;

SELECT pg_stat_force_next_flush();
SELECT n_live_tup, n_dead_tup FROM pg_stat_user_tables WHERE relname = 'counter';
-- 10000 | 20000

VACUUM (VERBOSE) counter;           -- reports the dead tuples it removed
SELECT pg_size_pretty(pg_table_size('counter'));   -- unchanged: space is reusable

-- tune a big, busy table instead of relying on the 20% default
ALTER TABLE counter SET (autovacuum_enabled = on,
                         autovacuum_vacuum_scale_factor = 0.01);

CREATE TABLE job (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
                  payload text, done boolean NOT NULL DEFAULT false);
INSERT INTO job (payload) SELECT 'job ' || g FROM generate_series(1, 5) g;

-- each worker runs this; concurrent workers get different rows
BEGIN;
SELECT id, payload FROM job
WHERE NOT done ORDER BY id
LIMIT 1 FOR UPDATE SKIP LOCKED;          -- 1 | job 1
UPDATE job SET done = true WHERE id = 1;
COMMIT;

-- who is blocked, and by whom?
SELECT pid, pg_blocking_pids(pid) AS blocked_by, wait_event_type,
       state, now() - xact_start AS xact_age, left(query, 60) AS query
FROM pg_stat_activity
WHERE cardinality(pg_blocking_pids(pid)) > 0;

CREATE TABLE event (
    id         bigint GENERATED ALWAYS AS IDENTITY,
    created_at timestamptz NOT NULL,
    kind       text,
    PRIMARY KEY (id, created_at)            -- must include the partition key
) PARTITION BY RANGE (created_at);
CREATE INDEX ON event (kind);               -- cascades to every partition

CREATE TABLE event_2026_05 PARTITION OF event
    FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');
CREATE TABLE event_2026_06 PARTITION OF event
    FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
INSERT INTO event (created_at, kind) VALUES ('2026-05-20', 'login'), ('2026-06-02', 'click');

EXPLAIN SELECT * FROM event WHERE created_at >= '2026-06-01';
-- scans only event_2026_06
ALTER TABLE event DETACH PARTITION event_2026_05 CONCURRENTLY;
DROP TABLE event_2026_05;                   -- instant retention

CREATE TABLE note (id int PRIMARY KEY, tenant_id int NOT NULL, body text);
INSERT INTO note VALUES (1, 1, 'tenant one'), (2, 2, 'tenant two');

CREATE ROLE web NOLOGIN;
GRANT SELECT, INSERT ON note TO web;
ALTER TABLE note ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON note TO web
    USING (tenant_id = current_setting('app.tenant_id')::int)
    WITH CHECK (tenant_id = current_setting('app.tenant_id')::int);

SET ROLE web;
SET app.tenant_id = '1';
SELECT id, body FROM note;                  -- 1 | tenant one   (only)
INSERT INTO note VALUES (3, 2, 'sneaky');
-- ERROR: new row violates row-level security policy for table "note"
