CREATE TABLE player (id int PRIMARY KEY, name text, score int)
WITH (fillfactor = 80);
INSERT INTO player SELECT g, 'p' || g, 0 FROM generate_series(1, 1000) g;

SELECT ctid, xmin, xmax, id FROM player WHERE id = 1;  -- (0,1) | 750 | 0 | 1
UPDATE player SET score = score + 10 WHERE id = 1;
SELECT ctid, xmin FROM player WHERE id = 1;            -- (0,..) new version, new xmin

UPDATE player SET score = score + 1 WHERE id % 10 = 0;  -- score isn't indexed
SELECT pg_stat_force_next_flush();
SELECT n_tup_upd, n_tup_hot_upd FROM pg_stat_user_tables WHERE relname = 'player';
-- 101 | 101: all HOT, the pages had free space (fillfactor 80)

